// A snippet's `category` may list several categories, so one snippet can appear
// under more than one tab. Accepts a comma-separated string ('120,107'), an array
// (['120','107']) or a single value ('120' / 120).
function snippetInCategory(item, cat) {
  cat = cat + '';
  const cats = Array.isArray(item.category) ? item.category : (item.category + '').split(',');
  return cats.some(c => (c + '').trim() === cat);
}

// Snippets browser — renders directly in the editor's [data-cb-ui] modal (no iframe).
// Data is already loaded in the parent window by loadSnippets() as opts.snippetJSON.
class Snippets {
  constructor(builder) {
    this.builder = builder;
    this.util = builder.util;
    this.dom = builder.dom; // shared Dom instance (avoids a module-load-order cycle)
  }

  // opts.snippetJSON.snippets is already canvas-filtered in loadSnippets().
  // Apply the runtime-dependent slider/form filters and (re)assign ids.
  getData() {
    const builder = this.builder;
    const json = builder.opts.snippetJSON;
    let snippets = json && json.snippets ? json.snippets.slice() : [];
    const slider = typeof builder.slider !== 'undefined' ? builder.slider : null;
    if (slider !== null) {
      if (slider === 'slick') snippets = snippets.filter(s => s.type !== 'glide');else if (slider === 'glide') snippets = snippets.filter(s => s.type !== 'slick');else if (slider === 'all') ; else snippets = snippets.filter(s => s.type !== 'glide' && s.type !== 'slick');
    } else {
      // Backward compatible: hide slider snippets whose lib isn't present.
      let hideSlick = true;
      if (builder.win.jQuery && builder.win.jQuery.fn && builder.win.jQuery.fn.slick) hideSlick = false;
      if (hideSlick) snippets = snippets.filter(s => s.type !== 'slick');
      if (!builder.win.Glide) snippets = snippets.filter(s => !(s.glide || s.type === 'glide'));
    }
    if (!builder.win.FormViewer) snippets = snippets.filter(s => s.type !== 'form');
    snippets.forEach((s, i) => {
      s.id = i + 1;
    });
    return snippets;
  }

  // Render the category tabs + thumbnail grid into the modal (.is-modal.snippets).
  render(modal) {
    const builder = this.builder;
    const util = this.util;
    this.modal = modal;
    this.snippets = this.getData();
    const tabsEl = modal.querySelector('.cb-tabs');
    const gridEl = modal.querySelector('.snippet-grid');
    if (!tabsEl || !gridEl) return;
    const cats = builder.opts.snippetCategories; // [[id,'Label'], …]
    const defaultCat = builder.opts.defaultSnippetCategory + '';
    tabsEl.innerHTML = cats.map(([id, label]) => {
      const on = id + '' === defaultCat;
      return `<button type="button" role="tab" data-tab="${id}" aria-selected="${on ? 'true' : 'false'}" tabindex="${on ? '0' : '-1'}">${util.out(label)}</button>`;
    }).join('');
    const renderGrid = catId => {
      catId = catId + '';
      gridEl.innerHTML = '';
      const frag = document.createDocumentFragment();
      this.snippets.filter(s => snippetInCategory(s, catId)).forEach(s => {
        const item = document.createElement('li');
        item.className = 'snippet-item';
        item.setAttribute('role', 'button');
        item.tabIndex = 0;
        item.setAttribute('data-id', s.id);
        item.innerHTML = `<img src="${builder.opts.snippetPath + s.thumbnail}" loading="lazy" alt=""><span class="is-overlay"></span>`;
        item.addEventListener('click', () => this.addSnippet(s.id));
        item.addEventListener('keydown', e => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            this.addSnippet(s.id);
          }
        });
        frag.appendChild(item);
      });
      gridEl.appendChild(frag);
      gridEl.scrollTop = 0;
    };

    // Shared, accessible tab kit (arrow keys, roving tabindex, overflow scroll).
    this.dom.accessibleTabs(tabsEl, tabId => renderGrid(tabId));
    this.dom.scrollableTabs(modal.querySelector('.cb-tabs-scroller'));
    renderGrid(defaultCat);
  }
  addSnippet(snippetid) {
    const builder = this.builder;
    const util = this.util;
    const snippets = this.snippets || [];
    const snippetPathReplace = builder.opts.snippetPathReplace;
    const emailMode = builder.opts.emailMode;
    let html;
    let noedit;
    for (let i = 0; i < snippets.length; i++) {
      if (snippets[i].id + '' === snippetid + '') {
        html = snippets[i].html;
        if (html.includes('"is-block')) html = snippets[i].html2; // canvas block variant
        noedit = snippets[i].noedit;
        break;
      }
    }
    if (html === undefined) return;
    let bSnippet = html.indexOf('"row') === -1; // not wrapped in a row/column grid
    if (emailMode) bSnippet = false;
    if (bSnippet) {
      // Opened via the quickadd (+) tool → insert as a bare snippet at that spot;
      // opened standalone (no mode) → wrap in a full-width row/column.
      const quickadd = builder.builderStuff.querySelector('.quickadd');
      const mode = quickadd ? quickadd.getAttribute('data-mode') : null;
      if (!mode) {
        html = '<div class="row"><div class="column full">' + html + '</div></div>';
        bSnippet = false;
      }
    }

    // Convert snippet markup into the host app's configured 12-column grid.
    const rowClass = builder.opts.row;
    const colClass = builder.opts.cols;
    if (rowClass !== '' && colClass.length === 12) {
      html = html.replace(/row clearfix/g, 'row'); // backward compatible
      html = html.replace(/"row/g, '"' + rowClass);
      html = html.replace(/column full/g, colClass[11]);
      html = html.replace(/column half/g, colClass[5]);
      html = html.replace(/column third/g, colClass[3]);
      html = html.replace(/column fourth/g, colClass[2]);
      html = html.replace(/column fifth/g, colClass[1]);
      html = html.replace(/column sixth/g, colClass[1]);
      html = html.replace(/column two-third/g, colClass[7]);
      html = html.replace(/column two-fourth/g, colClass[8]);
      html = html.replace(/column two-fifth/g, colClass[9]);
      html = html.replace(/column two-sixth/g, colClass[9]);
    }
    html = html.replace(/{id}/g, util.makeId()); // auto-id for custom-code snippets

    if (builder.opts.onAdd) html = builder.opts.onAdd(html);
    if (snippetPathReplace.length > 0 && snippetPathReplace[0] !== '') {
      let regex = new RegExp(snippetPathReplace[0], 'g');
      html = html.replace(regex, snippetPathReplace[1]);
      // …and the URL-encoded form (/ → %2F)
      const slash = /\//g;
      regex = new RegExp(snippetPathReplace[0].replace(slash, '%2F'), 'g');
      html = html.replace(regex, snippetPathReplace[1].replace(slash, '%2F'));
    }
    builder.addSnippet(html, bSnippet, noedit);
    util.hideModal(this.modal);
  }
}

