// hover:border-* classes stay. The stylesheet already carries the pair of
// them through :focus-visible, and border-current + hover:border-transparent
// has a rule of its own that makes the border follow the fill.
//
// Returns true if anything changed, so callers can tell a no-op from a real
// migration without diffing.
function migrateLegacyHover(el) {
  if (!el.hasAttribute('data-hover-bg')) return false;

  // Only OUR handlers. An element carrying an unrelated onmouseover, or a
  // data-hover-bg some integrator uses for their own purpose, is left alone.
  const over = el.getAttribute('onmouseover');
  if (over && over.indexOf('data-hover-bg') === -1) return false;
  const color = el.getAttribute('data-hover-bg');

  // data-bg is where the mouseout handler kept the base colour. Usually the
  // inline style has it too, but if the markup relied on the attribute alone
  // then dropping it would lose the base colour entirely.
  const base = el.getAttribute('data-bg');
  if (base && !el.style.backgroundColor) el.style.backgroundColor = base;
  if (color) {
    // writeHoverColor, not setHoverColor: this pass converts the hover
    // encoding and touches nothing else. applyDefault would add
    // whitespace-nowrap and role="button" to buttons whose authors did not
    // ask for them, during a pass the user never triggered.
    writeHoverColor(el, 'bg', color);

    // Only once the background really moved. A button whose data-hover-bg
    // is empty keeps no hover fill at all, and giving it an
    // attribute-driven hover text colour would create the mirror of the
    // problem this is here to avoid.
    const hoverText = readHoverColor(el, 'color');
    if (hoverText) writeHoverColor(el, 'color', hoverText);
  } else {
    el.removeAttribute('onmouseover');
    el.removeAttribute('onmouseout');
    el.removeAttribute('data-hover-bg');
    el.removeAttribute('data-bg');
  }
  return true;
}

// Migrate every legacy button under `root`. Idempotent and cheap once done:
// the selector matches nothing on content that has already been converted.
function migrateLegacyHoverIn(root) {
  if (!root || !root.querySelectorAll) return 0;
  let count = 0;
  root.querySelectorAll('[data-hover-bg]').forEach(el => {
    if (migrateLegacyHover(el)) count++;
  });
  return count;
}

// The same migration for a fragment of HTML that has not been inserted yet.
//
// This is the form the insert paths need: addSnippet() and the Sortable
// onAdd handlers all receive the snippet as a STRING and then branch several
// ways, some with early returns, so converting once at the entry is both
// simpler and more reliable than finding every place the markup lands.
//
// The guard matters. Markup with no legacy button is returned byte for byte,
// never parsed and never re-serialised, so the round trip touches only the
// content that actually needs converting.
function migrateLegacyHoverHtml(html) {
  if (typeof html !== 'string') return html;
  if (html.indexOf('data-hover-bg') === -1) return html;
  if (typeof document === 'undefined') return html;
  const holder = document.createElement('div');
  holder.innerHTML = html;
  if (migrateLegacyHoverIn(holder) === 0) return html;
  return holder.innerHTML;
}
function setHref(el, href) {
  if (el.tagName.toLowerCase() !== 'a') return;
  el.setAttribute('href', href);
}
function setNewTab(el, on) {
  if (on) el.setAttribute('target', '_blank');else el.removeAttribute('target');
}

// --- Presets -----------------------------------------------------------

// Adopt another button's look wholesale. Used by the preset gallery and by
// saved buttons: everything about the appearance is replaced, and only the
// element's own identity (its text, its href) survives.
function copyStyleFrom(target, source) {
  target.removeAttribute('style');
  target.removeAttribute('onmouseover');
  target.removeAttribute('onmouseout');
  target.removeAttribute('data-bg');
  target.removeAttribute('data-hover-bg');
  target.removeAttribute(HOVER_MARKER);
  target.setAttribute('class', source.getAttribute('class'));

  // The style attribute carries the hover custom properties along with
  // everything else, so the marker is all that has to be copied separately.
  if (source.hasAttribute('style')) target.setAttribute('style', source.getAttribute('style'));
  if (source.hasAttribute(HOVER_MARKER)) target.setAttribute(HOVER_MARKER, source.getAttribute(HOVER_MARKER));

  // A source still on the legacy form keeps it. Adopting a style is not the
  // user editing that button's hover colour, so it is not a licence to
  // rewrite how the source stored it.
  if (source.hasAttribute('onmouseover')) target.setAttribute('onmouseover', source.getAttribute('onmouseover'));
  if (source.hasAttribute('onmouseout')) target.setAttribute('onmouseout', source.getAttribute('onmouseout'));
  if (source.hasAttribute('data-bg')) {
    target.setAttribute('data-bg', source.getAttribute('data-bg'));
    target.style.backgroundColor = source.getAttribute('data-bg');
  }
  if (source.hasAttribute('data-hover-bg')) {
    target.setAttribute('data-hover-bg', source.getAttribute('data-hover-bg'));
  }
  target.classList.remove('active');
  target.classList.remove('elm-active');
  applyDefault(target);
}

// Compose a button from a preset config.
function generateButton(config) {
  const {
    type = 'outline',
    shape = 'rounded',
    size = 'medium',
    text = 'Button',
    color,
    bg,
    hoverBg,
    hoverColor,
    hoverBorder,
    borderColor,
    customClasses = '',
    href = '#'
  } = config;
  const preset = SIZE_PRESETS[size] || SIZE_PRESETS.medium;
  const sizeClasses = `py-${preset.py} px-${preset.px} size-${preset.size} leading-${preset.leading}`;
  let classes = `${BASE_CLASSES} ${SHAPE_CLASSES[shape] || ''} ${sizeClasses} ${customClasses}`.trim();

  // Remove 'no-underline' if 'underline' exists in customClasses
  if (/\bunderline\b/.test(customClasses)) {
    classes = classes.replace(/\bno-underline\b/, '').trim();
  }
  if (type === 'outline2') {
    const borderClass = borderColor ? '' : 'border-current hover:border-current';
    classes += ` ${borderClass}`;
    const styleAttr = color ? `style="color: ${color};"` : '';
    return {
      html: `<a href="${href}" role="button" class="${classes}"${styleAttr ? ' ' + styleAttr : ''}>${text}</a>`
    };
  }
  if (type === 'outline') classes += ' border-current hover:border-transparent';else if (type === 'solid') classes += ' border-transparent hover:border-transparent';else return undefined;
  let html = '<a\n';
  html += `  href="${href}"\n`;
  html += '  role="button"\n';
  html += `  class="${classes}"\n`;

  // Hover colours are custom properties alongside the base colours, and the
  // marker names the ones that were actually declared. A generated button is
  // therefore already on the current form: nothing here writes the inline
  // handlers any more.
  const styles = [];
  const aspects = [];
  if (color) styles.push(`color: ${color}`);
  if (bg) styles.push(`background-color: ${bg}`);
  if (bg && hoverBg) {
    styles.push(`${HOVER_VARS.bg}: ${hoverBg}`);
    aspects.push('bg');
  }
  if (hoverColor) {
    styles.push(`${HOVER_VARS.color}: ${hoverColor}`);
    aspects.push('color');
  }
  if (hoverBorder) {
    styles.push(`${HOVER_VARS.border}: ${hoverBorder}`);
    aspects.push('border');
  }
  if (styles.length) html += `  style="${styles.join('; ')};"`;
  if (aspects.length) html += `\n  ${HOVER_MARKER}="${aspects.join(' ')}"`;
  html += '>\n';
  html += `  ${text}\n`;
  html += '</a>';
  return {
    html
  };
}

