  loadLightboxFromCdn(callback) {
    // console.log('Please use assets from the latest package.');
    const url = 'https://cdnjs.cloudflare.com/ajax/libs/glightbox/3.2.0/js/glightbox.min.js';
    if (!this.isJsOnContentIncluded(url)) {
      const script = this.builder.doc.createElement('script');
      script.src = url;
      script.async = true;
      script.onload = () => {
        this.loadCssOnContent('https://cdnjs.cloudflare.com/ajax/libs/glightbox/3.2.0/css/glightbox.min.css');
        this.builder.doc.body.insertAdjacentHTML('beforeend', `<style id="_skin">${this.getLightboxCss()}</style>`);
        if (callback) callback(); // use default theme
      };

      this.builder.doc.body.appendChild(script);
    } else {
      if (!this.builder.doc.querySelector('#_skin')) {
        // in case a module load from cdn without skin
        this.builder.doc.body.insertAdjacentHTML('beforeend', `<style>${this.getLightboxCss()}</style>`);
      }
      if (callback) callback();
    }
  }
  loadLightboxScript(callback) {
    const url = this.builder.assetPath + 'scripts/glightbox/glightbox.min.js';
    if (!this.isJsOnContentIncluded(url)) {
      const script = this.builder.doc.createElement('script');
      script.src = url;
      script.async = true;
      script.onload = () => {
        // Test
        if (!this.builder.GLightbox) {
          this.loadLightboxFromCdn(callback);
        } else {
          this.loadCssOnContent(this.builder.assetPath + 'scripts/glightbox/glightbox.min.css');
          this.loadCssOnContent(this.builder.assetPath + 'scripts/glightbox/skin.css');
          if (callback) callback();
        }
      };
      this.builder.doc.body.appendChild(script);

      // If local not found
      script.onerror = () => {
        this.loadLightboxFromCdn(callback);
      };
    } else {
      if (callback) callback();
    }
  }
  refreshLightbox(options, callback) {
    if (this.builder.glightbox && this.builder.GLightbox) {
      this.builder.glightbox.destroy();
      this.builder.glightbox = this.builder.GLightbox(options);
      if (callback) callback();
    } else {
      this.loadLightboxScript(() => {
        this.builder.GLightbox = this.builder.win.GLightbox;
        this.builder.glightbox = this.builder.win.GLightbox(options);
        if (callback) callback();
      });
    }
  }
  openLightbox(url, options) {
    const elm = this.builder.openMediaElm;
    if (this.builder.glightbox) {
      if (this.builder.doc.body.classList.contains('glightbox-open')) {
        this.builder.glightbox.close();
        let overlay = this.builder.doc.querySelector('.goverlay'); // close other instance if exists
        if (overlay) overlay.click();
        setTimeout(() => {
          this.openLightbox(url, options);
        }, 400);
        return;
      }

      // this.builder.glightbox.setElements([
      //     {
      //       'href': url
      //     }
      // ]);

      let list = [];
      let open = 0;
      if (elm) {
        const gallery = elm.closest('[data-gallery]');
        let links = [];
        if (gallery) {
          links = gallery.querySelectorAll('.is-lightbox');
          links.forEach((link, index) => {
            let linkUrl = link.getAttribute('href');
            list.push({
              'href': linkUrl
            });
            if (url === linkUrl) open = index;
          });
        } else {
          let elms = this.builder.doc.querySelectorAll('.is-lightbox,.block-click');
          elms.forEach(elm => {
            // exclude galleries & the old lightbox: .is-lightbox.lightbox-all
            if (!elm.closest('[data-gallery]') && !elm.classList.contains('lightbox-all')) {
              links.push(elm);
            }
          });
          links.forEach((link, index) => {
            let linkUrl = link.getAttribute('href');
            if (!linkUrl) linkUrl = link.getAttribute('data-modal-url');
            list.push({
              'href': linkUrl
            });
            if (url === linkUrl) open = index;
          });
        }
      }
      if (list.length > 0) {
        this.builder.glightbox.setElements(list);
        this.builder.glightbox.openAt(open);
      } else {
        this.builder.glightbox.setElements([{
          'href': url
        }]);
        this.builder.glightbox.open();
      }
      this.builder.glightbox.on('close', () => {
        this.builder.glightbox.setElements([]);
        this.refreshLightbox(options);
      });
    }
    this.builder.openMediaElm = null;
  }
  isJsOnContentIncluded(src) {
    const scripts = this.builder.doc.getElementsByTagName('script');
    for (let i = 0; i < scripts.length; i++) if (scripts[i].getAttribute('src') === src) return true;
    return false;
  }
  loadCssOnContent(cssFile) {
    const link = this.builder.doc.createElement('link');
    link.href = cssFile;
    link.rel = 'stylesheet';
    this.builder.doc.head.appendChild(link);
  }
