const HEADER_MARK_ICON = '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="3" y="4" width="14" height="12" rx="1.5"/><path d="M3 8h14"/><path d="M3 4h14v4H3z" fill="currentColor" stroke="none"/></svg>';
class TableTool {
  constructor(builder) {
    this.builder = builder;
    this.toolbar = null;
    this.region = null; /* active InscribeRegion */
    this.table = null; /* the <table> the toolbar targets */
    this.styleDialog = new TableStyleDialog(builder);
    this.headerMarker = null; /* "Header" tag shown on a table's <thead> row */
    this._boundReposition = () => {
      if (this.visible) {
        this._position();
        this._updateHeaderMarker();
      }
    };
    this._boundDocDown = e => this._onDocDown(e);
  }
  get visible() {
    return this.toolbar && this.toolbar.classList.contains('active');
  }

  /* ---- build ----------------------------------------------------------- */

  _render() {
    if (this.toolbar) return;
    const builder = this.builder;
    const dom = builder.dom;
    const util = builder.util;
    const item = (cmd, label) => `<button type="button" class="tt-item" data-tcmd="${cmd}">${util.out(label)}</button>`;
    const html = `
      <div class="is-tool is-rte-table-tool" role="toolbar" aria-label="${util.out('Table')}">
        <div class="tt-drop">
          <button type="button" class="tt-ctl" data-menu="row" data-title="${util.out('Row')}">${util.out('Row')} <span class="tt-car">▾</span></button>
          <div class="tt-menu" data-menu-for="row">
            ${item('rowabove', 'Insert Above')}
            ${item('rowbelow', 'Insert Below')}
            <div class="tt-sep"></div>
            ${item('delrow', 'Delete Row')}
          </div>
        </div>
        <div class="tt-drop">
          <button type="button" class="tt-ctl" data-menu="col" data-title="${util.out('Column')}">${util.out('Column')} <span class="tt-car">▾</span></button>
          <div class="tt-menu" data-menu-for="col">
            ${item('colleft', 'Insert Left')}
            ${item('colright', 'Insert Right')}
            <div class="tt-sep"></div>
            ${item('delcol', 'Delete Column')}
          </div>
        </div>
        <span class="tt-sepv"></span>
        <button type="button" class="tt-ctl tt-icon" data-tcmd="merge" title="${util.out('Merge Cells')}" data-title="${util.out('Merge Cells')}">${ICONS.merge}</button>
        <button type="button" class="tt-ctl tt-icon" data-tcmd="split" title="${util.out('Split Cell')}" data-title="${util.out('Split Cell')}">${ICONS.split}</button>
        <button type="button" class="tt-ctl tt-icon" data-tcmd="header" title="${util.out('Toggle Header Row')}" data-title="${util.out('Toggle Header Row')}">${ICONS.header}</button>
        <span class="tt-sepv"></span>
        <button type="button" class="tt-ctl tt-icon tt-gear" data-tcmd="settings" title="${util.out('Table Settings')}" data-title="${util.out('Table Settings')}">${ICONS.gear}</button>
        <button type="button" class="tt-ctl tt-icon tt-danger" data-tcmd="deltable" title="${util.out('Delete Table')}" data-title="${util.out('Delete Table')}">${ICONS.trash}</button>
      </div>`;

    /* Editor CHROME lives in the MAIN-document builderStuff (like the
       element tool), never in the iframe: it keeps the shared _tokens.scss
       CSS available, and positioning over iframe content is done with the
       iframe-aware util.getElementPosition() (see _position). */
    dom.appendHtml(builder.builderStuff, html);
    this.toolbar = builder.builderStuff.querySelector('.is-rte-table-tool');
    this._ensureStyles(this.toolbar.ownerDocument);
    builder.setTooltip(this.toolbar); // Enable tooltip from data-title attributes

    /* mousedown only PREVENTS the default (keeps the editor's caret/
       selection — a toolbar press must not move focus). The action runs on
       CLICK. Acting on click (not mousedown) is what keeps dropdown menus
       correct: the menu stays open through the whole press, so the click's
       target is the button — which is inside .is-tool, so ContentBuilder's
       doDocumentClick skips clearControls() (it reads e.target.closest(
       '.is-tool')). Closing the menu on mousedown pulled the item out from
       under the pointer, so the click landed on <body> and hid the toolbar.
       (The old reason for acting on mousedown — clicks dropped when the
       toolbar hid mid-press — is gone: visibility is caret-driven now.) */
    this.toolbar.addEventListener('mousedown', e => {
      if (e.target.closest('button')) e.preventDefault();
    });
    this.toolbar.addEventListener('click', e => {
      const btn = e.target.closest('button[data-tcmd], button[data-menu]');
      if (!btn || btn.disabled) return;
      const menu = btn.getAttribute('data-menu');
      if (menu) {
        this._toggleMenu(menu);
        return;
      }
      this._closeMenus();
      this._exec(btn.getAttribute('data-tcmd'));
    });
    this.builder.win.addEventListener('scroll', this._boundReposition, true);
    window.addEventListener('scroll', this._boundReposition, true);
    window.addEventListener('resize', this._boundReposition);
    this._bindCellClick();
  }
  _ensureStyles(doc) {
    if (!doc || doc.getElementById(STYLE_ID)) return;
    const st = doc.createElement('style');
    st.id = STYLE_ID;
    /* A floating pill layered on the base .is-tool (which supplies position,
       the .active display toggle, and ContentBuilder tool integration). All
       colours come from the ROLE-based tokens in _tokens.scss (surface, text,
       line, fill, elevation, danger) — no component-scoped tokens — so any
       other floating tool reuses the same set. Overrides beat the base
       .is-tool rules with !important where the base is specific. */
    st.textContent = `
      .is-rte-table-tool {
        position: absolute; top: 0; left: 0; z-index: 10001;
        display: none; box-sizing: border-box;
        border: none !important;
        border-radius: 100px !important;
        box-shadow: var(--cb-shadow) !important;
        background-color: var(--cb-float-surface) !important;
        width: auto; height: 36px;
        align-items: center; gap: 2px;
        padding: 0 5px !important;
        overflow: visible !important;
      }
      .is-rte-table-tool.active { display: flex; }
      .is-rte-table-tool .tt-ctl {
        display: inline-flex; align-items: center; justify-content: center; gap: 5px;
        width: 32px !important; height: 31px; padding: 0 10px !important;
        background: transparent !important; color: var(--cb-text);
        border: none; border-radius: 100px; cursor: pointer;
        font-size: 12.5px; line-height: 1; white-space: nowrap;
        text-transform: none; letter-spacing: 0;
      }
      .is-rte-table-tool .tt-drop .tt-ctl {
        padding: 0 7px !important;
        width: auto !important;
        height: 31px !important;
        color: var(--cb-text) !important;
        background: var(--cb-surface) !important;
      }
      .is-rte-table-tool .tt-ctl.tt-icon { width: 32px; padding: 0; }
      .is-rte-table-tool .tt-ctl svg { width: 15px; height: 15px; stroke: currentColor; fill: none !important; flex: none; }
      .is-rte-table-tool .tt-ctl:hover:not(:disabled) { background: var(--cb-fill-hover); }
      .is-rte-table-tool .tt-ctl:disabled { opacity: .35; cursor: default; }
      .is-rte-table-tool .tt-ctl.tt-active { background: var(--cb-fill-active); }
      .is-rte-table-tool .tt-gear { color: var(--cb-accent); }
      .is-rte-table-tool .tt-danger:hover:not(:disabled) { background: var(--cb-danger-fill); color: var(--cb-danger); }
      .is-rte-table-tool .tt-car { font-size: 8px; opacity: .55; }
      .is-rte-table-tool .tt-sepv { width: 1px; height: 20px; background: var(--cb-line); margin: 0 2px; }
      .is-rte-table-tool .tt-drop { position: relative; display: inline-flex; }
      .is-rte-table-tool .tt-menu {
        position: absolute; top: calc(100% + 8px); left: 0; min-width: 160px; padding: 8px 0px 0px !important;
        background: var(--cb-surface); border: 1px solid var(--cb-line);
        box-shadow: var(--cb-shadow-lg);
        border-radius: 10px; overflow: hidden; padding: 5px; display: none; z-index: 3;
      }
      .is-rte-table-tool .tt-drop.open .tt-menu { display: block; }
      .is-rte-table-tool .tt-menu .tt-item {
        display: block !important; width: 100% !important; height: 35px !important; text-align: left !important; padding: 8px 14px !important;
        font-size: 13px; line-height: 1; color: var(--cb-text); background: transparent !important; border: none;
        border-radius: 6px; cursor: pointer; text-transform: none; letter-spacing: 0; box-shadow: none  !important;
      }
      .is-rte-table-tool .tt-menu .tt-item:hover:not(:disabled) { background: var(--cb-accent-fill-3) !important; }
      .is-rte-table-tool .tt-menu .tt-item:disabled { opacity: .35; cursor: default; }
      .is-rte-table-tool .tt-menu .tt-sep { height: 1px; background: var(--cb-line-2); margin: 4px 4px; }
      /* button contents never catch pointer events: the <button> stays the
         event target */
      .is-rte-table-tool .tt-ctl svg,
      .is-rte-table-tool .tt-ctl .tt-car { pointer-events: none; }

      /* "Header" marker on the thead row */
      .is-rte-table-header-marker {
        position: absolute; top: 0; left: 0; z-index: 10001;
        display: none; align-items: center; gap: 4px;
        font-family: var(--sans, inherit); font-size: 10px; font-weight: 700;
        letter-spacing: .05em; text-transform: uppercase;
        color: var(--cb-accent); background: var(--cb-accent-fill);
        border: 1px solid var(--cb-accent-line); border-radius: 5px;
        padding: 3px 7px; white-space: nowrap; pointer-events: none; box-sizing: border-box;
      }
      .is-rte-table-header-marker.active { display: inline-flex; }
      .is-rte-table-header-marker svg { width: 11px; height: 11px; }
    `;
    (doc.head || doc.documentElement).appendChild(st);
  }

  /* ---- probe -> show / position / enable ------------------------------- */

  onProbe(state, region) {
    /* Visibility is CARET-driven only (never focus/blur): in a table ->
       show; anywhere else -> hide. Toolbar interactions blur the editor
       but keep the caret in the cell, so the toolbar stays put. */
    if (!state || !state.table || state.readOnly) {
      this.hide();
      return;
    }
    this.region = region;
    const table = this._activeTable(region);
    if (!table) {
      this.hide();
      return;
    }
    this._render();
    this.table = table;
    this._refresh(state);
    this.toolbar.classList.add('active');
    this._position();
    this._updateHeaderMarker();
    /* the style dialog is modeless and tracks table clicks itself
       (see TableStyleDialog._track); no coupling needed here */
    this._bindDocDown();
  }
  hide() {
    this._closeMenus();
    this.region = null;
    this.table = null;
    if (this.toolbar) this.toolbar.classList.remove('active');
    this._hideHeaderMarker();
    this._unbindDocDown();
  }
  _refresh(state) {
    const q = cmd => this.toolbar.querySelector(`[data-tcmd="${cmd}"]`);
    const setDisabled = (el, dis) => {
      if (el && el.disabled !== dis) el.disabled = dis;
    };

    /* Two independent buttons — no swap. Merge works on a selected region
       (any shape) OR, with just a caret, with an adjacent cell that forms a
       rectangle: a right neighbor merges right, and a cell with no right
       neighbor (e.g. the last cell in a row) merges DOWN. Split needs a
       spanning cell. */
    const canMerge = state.cellSelection ? !!state.canMergeRegion : !!state.canMergeRight || !!state.canMergeDown;
    setDisabled(q('merge'), !canMerge);
    setDisabled(q('split'), !state.canSplit);
    const header = q('header');
    if (header) header.classList.toggle('tt-active', state.cell === 'th');
  }
  _exec(cmd) {
    const region = this.region;
    if (!region || !region.ed) return;
    const ed = region.ed;
    const st = ed.probe() || {};
    switch (cmd) {
      case 'rowabove':
        ed.addRow('above');
        break;
      case 'rowbelow':
        ed.addRow('below');
        break;
      case 'delrow':
        ed.deleteRow();
        break;
      case 'colleft':
        ed.addColumn('before');
        break;
      case 'colright':
        ed.addColumn('after');
        break;
      case 'delcol':
        ed.deleteColumn();
        break;
      case 'merge':
        /* region if one is selected; otherwise merge with the neighbor that
           forms a rectangle — right if there is one, else down */
        if (st.cellSelection && st.canMergeRegion) ed.mergeRegion();else if (st.canMergeRight) ed.mergeCell('right');else if (st.canMergeDown) ed.mergeCell('down');
        break;
      case 'split':
        ed.splitCell();
        break;
      case 'header':
        ed.toggleHeader();
        break;
      case 'settings':
        this._openSettings();
        break;
      case 'deltable':
        ed.deleteTable();
        this.hide();
        break;
    }
  }

  /* Snapshot the target at open time: opening the modal can blur the
     editor (which hides the toolbar and clears this.table), so a live
     getter would read null. Styling makes no structural change, so the
     snapshot stays valid for the dialog's lifetime. */
  _openSettings() {
    const table = this.table;
    const cell = this._activeCell();
    if (!table || !cell) return;
    this.styleDialog.open(() => ({
      table,
      cell
    }));
  }

  /* ---- dropdown menus -------------------------------------------------- */

  _toggleMenu(which) {
    const drop = this.toolbar.querySelector(`[data-menu-for="${which}"]`).parentNode;
    const wasOpen = drop.classList.contains('open');
    this._closeMenus();
    if (!wasOpen) drop.classList.add('open');
  }
  _closeMenus() {
    if (!this.toolbar) return;
    this.toolbar.querySelectorAll('.tt-drop.open').forEach(d => d.classList.remove('open'));
  }

  /* Since visibility is no longer tied to editor blur, this is the
     click-away that dismisses the toolbar: a press outside the toolbar
     AND outside any table (and not on the styling dialog / colour picker)
     hides it. A press inside a table cell is left to the probe, which
     re-anchors the toolbar to that table. */
  _onDocDown(e) {
    const t = e.target;
    if (!this.toolbar || !t || !t.closest) return;
    if (t.closest('.is-rte-table-tool')) return; /* the toolbar itself */
    this._closeMenus();
    if (t.closest('table')) return; /* another cell — probe handles it */
    const pickerOpen = document.querySelector('.pop-picker.active') || document.querySelector('.pickgradientcolor.active');
    if (pickerOpen || t.closest('.is-modal') || t.closest('.is-sidebar')) return;
    this.hide();
  }
  _bindDocDown() {
    if (this._docDownBound) return;
    this._docDownBound = true;
    this.builder.doc.addEventListener('mousedown', this._boundDocDown, true);
    if (this.builder.doc !== document) document.addEventListener('mousedown', this._boundDocDown, true);
  }
  _unbindDocDown() {
    if (!this._docDownBound) return;
    this._docDownBound = false;
    this.builder.doc.removeEventListener('mousedown', this._boundDocDown, true);
    if (this.builder.doc !== document) document.removeEventListener('mousedown', this._boundDocDown, true);
  }

  /* Re-show on a click into a table cell even when the caret DOESN'T move.
     Visibility is otherwise probe-driven (selectionchange), so after the
     toolbar is dismissed by opening another pop (quick-add / More), clicking
     the SAME cell again wouldn't bring it back (no selection change → no
     probe). Persistent (bound once, independent of visibility). No-op while
     already visible — probe keeps it in sync then. */
  _bindCellClick() {
    if (this._cellClickBound) return;
    this._cellClickBound = true;
    this._boundCellClick = e => this._onCellClick(e);
    this.builder.doc.addEventListener('click', this._boundCellClick, false);
    if (this.builder.doc !== document) document.addEventListener('click', this._boundCellClick, false);
  }
  _unbindCellClick() {
    if (!this._cellClickBound) return;
    this._cellClickBound = false;
    this.builder.doc.removeEventListener('click', this._boundCellClick, false);
    if (this.builder.doc !== document) document.removeEventListener('click', this._boundCellClick, false);
  }
  _onCellClick(e) {
    if (this.visible) return;
    const t = e.target;
    if (!t || !t.closest) return;
    const cell = t.closest('td,th');
    if (!cell) return;
    const col = cell.closest('[contenteditable]');
    if (!col) return;
    const engine = this.builder.editingEngine;
    const region = engine && engine.regionFor ? engine.regionFor(col) : null;
    if (!region) return;
    const st = region.ed.probe();
    if (st) this.onProbe(st, region);
  }

  /* ---- geometry -------------------------------------------------------- */

  /* The <table> the caret / cell-region lives in, within this region. */
  _activeTable(region) {
    const ui = region.ed.tableUI;
    if (ui && ui.active && ui.table) return ui.table;
    const cell = this._selCell(region);
    return cell ? cell.closest('table') : null;
  }

  /* The active cell — region anchor, else the caret's cell. */
  _activeCell() {
    if (!this.region) return null;
    const ui = this.region.ed.tableUI;
    if (ui && ui.active && ui.anchor) return ui.anchor;
    return this._selCell(this.region);
  }
  _selCell(region) {
    const sel = this.builder.doc.getSelection ? this.builder.doc.getSelection() : null;
    let node = sel && sel.anchorNode;
    if (!node) return null;
    if (node.nodeType === 3) node = node.parentNode;
    const cell = node && node.closest ? node.closest('td,th') : null;
    return cell && region.el.contains(cell) ? cell : null;
  }

  /* Anchor to the table's TOP-RIGHT corner (right-aligned), just above
     the top edge; flip just inside the top when there's no room above. */
  _position() {
    if (!this.toolbar || !this.table) return;
    const tool = this.toolbar;
    const toolW = tool.offsetWidth;
    const toolH = tool.offsetHeight;
    /* getElementPosition() returns the table's MAIN-viewport top/left
       (adds the iframe offset + scale in iframe mode; plain rect otherwise).
       The tool lives in the main document, so scroll is window.pageYOffset. */
    const pos = this.builder.util.getElementPosition(this.table);
    const rect = this.table.getBoundingClientRect();
    const rightEdge = pos.left + rect.width * pos.scaleX; /* table's right in main viewport */
    const pageY = window.pageYOffset;
    let top = pos.top + pageY - toolH - 6;
    if (pos.top - toolH - 6 < 0) top = pos.top + pageY + 4;
    let left = rightEdge - toolW;
    const screenW = window.innerWidth;
    if (left + toolW > screenW) left = screenW - toolW - 8;
    if (left < 8) left = 8;
    tool.style.top = top + 'px';
    tool.style.left = left + 'px';
  }

  /* ---- header marker --------------------------------------------------- */

  /* A small "Header" tag on the table's <thead> row while it's being
     edited, so the header reads as special (and its pinned-to-the-top
     behaviour doesn't look like a bug). Editor chrome — not content — so it
     never touches the saved HTML. Sits at the header row's left (the future
     row-gutter position); tucks just inside if there's no room outside. */
  _ensureHeaderMarker() {
    if (this.headerMarker) return;
    const builder = this.builder;
    builder.dom.appendHtml(builder.builderStuff, `<div class="is-rte-table-header-marker">${HEADER_MARK_ICON}<span>${builder.util.out('Header')}</span></div>`);
    this.headerMarker = builder.builderStuff.querySelector('.is-rte-table-header-marker');
  }
  _updateHeaderMarker() {
    const thead = this.table && this.table.tHead;
    const headRow = thead && thead.rows[0];
    if (!headRow) {
      this._hideHeaderMarker();
      return;
    }
    this._ensureHeaderMarker();
    const m = this.headerMarker;
    m.classList.add('active');
    const pos = this.builder.util.getElementPosition(headRow);
    const rect = headRow.getBoundingClientRect();
    const pageY = window.pageYOffset;
    const top = pos.top + pageY + (rect.height * pos.scaleY - m.offsetHeight) / 2;
    let left = pos.left - m.offsetWidth - 6; /* left gutter */
    if (left < 4) left = pos.left + 4; /* no room outside -> tuck inside */
    m.style.top = top + 'px';
    m.style.left = left + 'px';
  }
  _hideHeaderMarker() {
    if (this.headerMarker) this.headerMarker.classList.remove('active');
  }
  destroy() {
    this.builder.win.removeEventListener('scroll', this._boundReposition, true);
    window.removeEventListener('scroll', this._boundReposition, true);
    window.removeEventListener('resize', this._boundReposition);
    this._unbindDocDown();
    this._unbindCellClick();
    if (this.headerMarker && this.headerMarker.parentNode) this.headerMarker.parentNode.removeChild(this.headerMarker);
    this.headerMarker = null;
    if (this.toolbar && this.toolbar.parentNode) this.toolbar.parentNode.removeChild(this.toolbar);
    this.toolbar = null;
  }
}

class SaveImages {
  constructor(opts = {}, builder) {
    let defaults = {
      page: '',
      container: '.container',
      handler: 'saveimage.php',
      onComplete: function () {},
      customval: '',
      stuffPlacement: '[data-cb-ui]',
      hiquality: false
      // onBase64Upload: function () { },
    };

    this.opts = Object.assign(this, defaults, opts);
    this.builder = builder;
    const dom = this.builder.dom;
    this.dom = dom;
    this.count = 0;
    let builderStuff = document.querySelector(this.opts.stuffPlacement);
    if (!builderStuff) {
      builderStuff = document.createElement('div');
      // builderStuff.id = '_cbhtml';
      // builderStuff.className = 'is-ui';
      builderStuff.setAttribute('data-cb-ui', '');
      dom.appendChild(document.body, builderStuff);
    }
    this.builderStuff = builderStuff;
  }
  save() {
    if (this.opts.page !== '') {
      let area = this.builder.doc.querySelector(this.opts.page);
      this.uploadImages(area);
    } else {
      let areas = this.builder.doc.querySelectorAll(this.opts.container);
      Array.prototype.forEach.call(areas, area => {
        this.uploadImages(area);
      });
    }

    //Check per 2 sec if all images have been changed with the new saved images.
    var int = setInterval(() => {
      let finished = true;
      if (this.opts.page !== '') {
        let area = this.builder.doc.querySelector(this.opts.page);
        finished = this.checkImages(area);
      } else {
        let areas = this.builder.doc.querySelectorAll(this.opts.container);
        Array.prototype.forEach.call(areas, area => {
          if (this.checkImages(area) === false) {
            finished = false;
          }
        });
      }
      if (finished) {
        try {
          this.opts.onComplete();
        } catch (e) {
          // Do Nothing
        }
        window.clearInterval(int);

        // No need to remove hidden iframes
        // //remove unused forms (previously used for submitting images)
        // for (var i = 1; i <= this.count; i++) {
        //     let frm = this.builderStuff.querySelector('#form-' + i);
        //     frm.parentNode.removeChild(frm);
        // }
      }
    }, 2000);
  }
  checkImages(area) {
    const images = area.querySelectorAll('img');
    let returnVal = true;
    Array.prototype.forEach.call(images, img => {
      let src = img.getAttribute('src');
      if (typeof src !== typeof undefined && src !== false) {
        if (src.indexOf('base64') !== -1) {
          //if there is still base64 image, means not yet finished.
          returnVal = false;
        }
      }
    });
    return returnVal;
  }
  uploadImages(area) {
    if (!area) return;

    //Check all images

    const divs = area.querySelectorAll('.is-overlay-bg,.is-container > div > div,.is-lightbox,.block-click');
    divs.forEach(div => {
      let src = '';
      if (div.style.backgroundImage && div.style.backgroundImage.includes('base64')) {
        if (div.style.backgroundImage.indexOf('url(') !== -1) {
          src = div.style.backgroundImage.slice(4, -1).replace(/["']/g, '');
        }
      } else if (div.classList.contains('is-lightbox') && div.getAttribute('href').includes('base64')) {
        src = div.getAttribute('href');
      } else if (div.classList.contains('block-click') && div.style.backgroundImage && !div.style.backgroundImage.includes('base64')) {
        src = div.getAttribute('data-modal-url');
      }
      if (src.includes('base64')) {
        if (this.opts.onBase64Upload) {
          let ext = 'jpg';
          if (src.includes('image/png')) {
            ext = 'png';
          }

          //Read image (base64 string)
          let image = src;
          image = image.replace(/^data:image\/(png|svg\+xml|jpeg);base64,/, '');
          let filename;
          if (div.hasAttribute('data-filename')) {
            filename = div.getAttribute('data-filename');
          } else {
            filename = this.builder.util.makeId() + '.' + ext;
          }

          // console.log(div)
          this.opts.onBase64Upload(div, image, filename); // target image, base64 string, filename
        }
      }
    });

    const images = area.querySelectorAll('img');
    Array.prototype.forEach.call(images, img => {
      let src = img.getAttribute('src');
      if (typeof src !== typeof undefined && src !== false && img.getAttribute('data-filename')) {
        if (src.indexOf('base64') !== -1) {
          // let customcode = false;
          // if(dom.parentsHasAttribute(img, 'data-html')){
          //     customcode = true;
          // }
          // let subblock = false;
          // if(dom.parentsHasAttribute(img, 'data-subblock')){
          //     subblock = true;
          // }
          // if(!customcode || (customcode && subblock)) {

          // }

          if (this.opts.onBase64Upload) {
            //Read image (base64 string)
            let image = src;
            image = image.replace(/^data:image\/(png|svg\+xml|jpeg);base64,/, '');
            let filename = img.getAttribute('data-filename');
            this.opts.onBase64Upload(img, image, filename); // target image, base64 string, filename
          } else {
            this.count++;

            //Read image (base64 string)
            let image = src;
            image = image.replace(/^data:image\/(png|svg\+xml|jpeg);base64,/, '');

            //Prepare form to submit image
            if (!this.builderStuff.querySelector('#form-' + this.count)) {
              var html = '<form id="form-' + this.count + '" target="frame-' + this.count + '" method="post" enctype="multipart/form-data">' + '<input id="hidimg-' + this.count + '" name="hidimg-' + this.count + '" type="hidden" />' + '<input id="hidname-' + this.count + '" name="hidname-' + this.count + '" type="hidden" />' + '<input id="hidtype-' + this.count + '" name="hidtype-' + this.count + '" type="hidden" />' + '<input id="hidcustomval-' + this.count + '" name="hidcustomval-' + this.count + '" type="hidden" />' + '' + '<input name="count" value="' + this.count + '" type="hidden" />' + '<iframe tabindex="0" id="frame-' + this.count + '" name="frame-' + this.count + '" style="width:1px;height:1px;border:none;position:absolute;z-index:-100000;left:-5px;"></iframe>' + '</form>';
              this.builderStuff.insertAdjacentHTML('beforeend', html);
            }

            //Give ID to image
            img.setAttribute('id', 'img-' + this.count);

            //Set hidden field with image (base64 string) to be submitted
            this.builderStuff.querySelector('#hidimg-' + this.count).value = image;

            //Set hidden field with custom value to be submitted
            this.builderStuff.querySelector('#hidcustomval-' + this.count).value = this.customval;

            //Set hidden field with file name to be submitted
            let filename = img.getAttribute('data-filename');
            if (filename) {
              let filename_without_ext = filename.substr(0, filename.lastIndexOf('.')) || filename;
              filename_without_ext = filename_without_ext.toLowerCase().replace(/ /g, '-');
              this.builderStuff.querySelector('#hidname-' + this.count).value = filename_without_ext;
            }

            //Set hidden field with file extension to be submitted
            if (this.opts.hiquality) {
              //If high quality is set true, set image as png
              this.builderStuff.querySelector('#hidtype-' + this.count).value = 'png'; //high quality
            } else {
              //If high quality is set false, depend on image extension
              var extension = filename.substr(filename.lastIndexOf('.') + 1);
              extension = extension.toLowerCase();
              if (extension === 'jpg' || extension === 'jpeg') {
                this.builderStuff.querySelector('#hidtype-' + this.count).value = 'jpg';
              } else {
                this.builderStuff.querySelector('#hidtype-' + this.count).value = 'png';
              }
            }

            //Submit form
            this.builderStuff.querySelector('#form-' + this.count).setAttribute('action', this.opts.handler + (this.opts.handler.indexOf('?') >= 0 ? '&' : '?') + 'count=' + this.count);
            this.builderStuff.querySelector('#form-' + this.count).submit();

            //Note: the submitted image will be saved on the server 
            //by saveimage.php (if using PHP) or saveimage.ashx (if using .NET)
            //and the image src will be changed with the new saved image.
          }
        }
      }
    });
  }
}

const dom = new Dom();
class Tooltip {
  constructor(builder) {
    this.builder = builder;
    const util = this.builder.util;
    const builderStuff = this.builder.builderStuff;
    this.util = util;
    this.builderStuff = builderStuff;
    let tooltip = builderStuff.querySelector('.is-tooltip');
    if (!tooltip) {
      let html = '<div class="is-tooltip"></div>';
      dom.appendHtml(builderStuff, html);
      tooltip = builderStuff.querySelector('.is-tooltip');
    }
    this.tooltip = tooltip;
  }
  setAll(o) {
    let area;
    if (!o) area = this.builderStuff;else area = o;
    //let elms = Array.prototype.slice.call(this.builderStuff.querySelectorAll('[data-title]')).concat(Array.prototype.slice.call(document.querySelectorAll('.is-builder .is-tool [data-title]')));
    let elms = area.querySelectorAll('[data-title]');
    Array.prototype.forEach.call(elms, elm => {
      this.set(elm, 0, 0);
    });
    if (this.builder.iframe) {
      if (!o) {
        let elms = this.builder.contentStuff.querySelectorAll('[data-title]');
        Array.prototype.forEach.call(elms, elm => {
          this.set(elm, 0, 0, true);
        });
      }
    }
  }
  set(elm, topadj, leftadj, iframe) {
    if (!topadj) topadj = 0;
    if (!leftadj) leftadj = 0;
    let tooltip = this.tooltip;
    elm.addEventListener('mouseover', e => {
      var relTarget = e.relatedTarget;
      if (this === relTarget || isAChildOf(this, relTarget)) return;
      const style = window.getComputedStyle(elm.parentNode);
      let direction = style.getPropertyValue('flex-direction');
      //console.log(style.flexDirection); 

      let s = elm.getAttribute('data-title');
      tooltip.innerHTML = s;
      let top, left;
      top = elm.getBoundingClientRect().top + window.pageYOffset;
      left = elm.getBoundingClientRect().left + window.pageXOffset;

      /*
      if(iframe) {
          let adjY = this.builder.iframe.getBoundingClientRect().top + window.pageYOffset;
          let adjX = this.builder.iframe.getBoundingClientRect().left + window.pageXOffset;
           top = elm.getBoundingClientRect().top + adjY;
          left = elm.getBoundingClientRect().left + adjX;
      }
      */

      if (iframe) {
        const newPos = this.util.getElementPosition(elm);
        top = newPos.top;
        left = newPos.left;
      }

      //console.log(top + ' - ' + left);
      tooltip.style.display = 'flex';
      tooltip.style.whiteSpace = 'nowrap';
      const w = elm.offsetWidth; //to get value, element must not hidden (display:none). So set display:flex before this.
      const h = elm.offsetHeight;
      tooltip.style.marginRight = ''; //reset

      const viewportWidth = window.innerWidth;
      tooltip.style.top = top + h + 5 + topadj + 'px';
      if (h < 30) {
        tooltip.style.top = top + h + 2 + topadj + 'px';
      }
      if (direction === 'column') {
        tooltip.style.top = top + h / 2 - tooltip.offsetHeight / 2 + topadj + 'px';
        tooltip.style.left = left + w + 3 + leftadj + 'px';
        if (viewportWidth - (left + w) < 100) {
          // 100 or tooltip.offsetWidth
          tooltip.style.left = left - tooltip.offsetWidth - 3 + leftadj + 'px';
        }
      } else {
        let tooltipLeft = left + w / 2 - tooltip.offsetWidth / 2 + leftadj;
        tooltip.style.left = tooltipLeft + 'px'; // center

        // Adjustment for snippet handle tooltip (or any other that is outside viewport)
        let rightedge = tooltipLeft + tooltip.offsetWidth;
        if (rightedge > viewportWidth) {
          let adj = rightedge - viewportWidth;
          tooltip.style.left = tooltipLeft - adj - 3 + 'px'; //3 = additional adjustment

          if (tooltip.offsetHeight > 25) tooltip.style.marginRight = '5px'; // to fix incorrect position if tooltip has more than 1 line
        }

        if (tooltipLeft < 0) {
          tooltip.style.left = '3px';
        }
      }

      // overide
      let tipOnTop = elm.hasAttribute('data-tooltip-top');
      if (tipOnTop) {
        tooltip.style.top = top - tooltip.offsetHeight - 3 + 'px'; //10 = additional adjustment
      }

      elm.removeAttribute('title');
    }, false);
    elm.addEventListener('mouseout', e => {
      var relTarget = e.relatedTarget;
      if (this === relTarget || isAChildOf(this, relTarget)) return;
      elm.setAttribute('title', elm.getAttribute('data-title'));
      tooltip.style.display = 'none';
    }, false);
    elm.addEventListener('click', e => {
      var relTarget = e.relatedTarget;
      if (this === relTarget || isAChildOf(this, relTarget)) return;
      elm.setAttribute('title', elm.getAttribute('data-title'));
      tooltip.style.display = 'none';
    }, false);
  }
  set2(elm, topadj, leftadj) {
    if (!topadj) topadj = 0;
    if (!leftadj) leftadj = 0;
    let tooltip = this.tooltip;
    elm.addEventListener('mouseover', e => {
      var relTarget = e.relatedTarget;
      if (this === relTarget || isAChildOf(this, relTarget)) return;
      const style = window.getComputedStyle(elm.parentNode);
      let direction = style.getPropertyValue('flex-direction');
      //console.log(style.flexDirection); 

      let s = elm.getAttribute('data-title');
      tooltip.innerHTML = s;
      const top = elm.getBoundingClientRect().top + window.pageYOffset;
      const left = elm.getBoundingClientRect().left + window.pageXOffset;
      //console.log(top + ' - ' + left);
      tooltip.style.display = 'flex';
      tooltip.style.whiteSpace = 'nowrap';
      const w = elm.offsetWidth; //to get value, element must not hidden (display:none). So set display:flex before this.
      const h = elm.offsetHeight;
      tooltip.style.marginRight = ''; //reset

      const viewportWidth = window.innerWidth;
      tooltip.style.top = top + h + 5 + topadj + 'px';
      if (h < 30) {
        tooltip.style.top = top + h + 2 + topadj + 'px';
      }
      if (direction === 'column') {
        tooltip.style.top = top + h / 2 - tooltip.offsetHeight / 2 + topadj + 'px';
        tooltip.style.left = left + w + 3 + leftadj + 'px';
        if (viewportWidth - (left + w) < 100) {
          // 100 or tooltip.offsetWidth
          tooltip.style.left = left - tooltip.offsetWidth - 3 + leftadj + 'px';
        }
      } else {
        let tooltipLeft = left + w / 2 - tooltip.offsetWidth / 2 + leftadj;
        tooltip.style.left = tooltipLeft + 'px'; // center

        // Adjustment for snippet handle tooltip (or any other that is outside viewport)
        let rightedge = tooltipLeft + tooltip.offsetWidth;
        if (rightedge > viewportWidth) {
          let adj = rightedge - viewportWidth;
          tooltip.style.left = tooltipLeft - adj - 3 + 'px'; //3 = additional adjustment

          if (tooltip.offsetHeight > 25) tooltip.style.marginRight = '5px'; // to fix incorrect position if tooltip has more than 1 line
        }

        if (tooltipLeft < 0) {
          tooltip.style.left = '3px';
        }
      }

      // overide
      let tipOnTop = elm.hasAttribute('data-tooltip-top');
      if (tipOnTop) {
        tooltip.style.top = top - tooltip.offsetHeight - 3 + 'px'; //10 = additional adjustment
      }

      elm.removeAttribute('title');
    }, false);
    elm.addEventListener('mouseout', e => {
      var relTarget = e.relatedTarget;
      if (this === relTarget || isAChildOf(this, relTarget)) return;
      elm.setAttribute('title', elm.getAttribute('data-title'));
      tooltip.style.display = 'none';
    }, false);
    elm.addEventListener('click', e => {
      var relTarget = e.relatedTarget;
      if (this === relTarget || isAChildOf(this, relTarget)) return;
      elm.setAttribute('title', elm.getAttribute('data-title'));
      tooltip.style.display = 'none';
    }, false);
  }
}

// https://stackoverflow.com/questions/8399408/mouseover-mouseout-eventlistener-inheriting-to-child-nodes
function isAChildOf(parent, child) {
  if (parent === child) {
    return false;
  }
  while (child && child !== parent) {
    child = child.parentNode;
  }
  return child === parent;
}

const uid = Date.now();

/**
 * Merge two or more objects
 */
function extend() {
  let extended = {};
  let deep = true;
  let i = 0;
  let length = arguments.length;
  if (Object.prototype.toString.call(arguments[0]) === '[object Boolean]') {
    deep = arguments[0];
    i++;
  }
  let merge = obj => {
    for (let prop in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, prop)) {
        if (deep && Object.prototype.toString.call(obj[prop]) === '[object Object]') {
          extended[prop] = extend(true, extended[prop], obj[prop]);
        } else {
          extended[prop] = obj[prop];
        }
      }
    }
  };
  for (; i < length; i++) {
    let obj = arguments[i];
    merge(obj);
  }
  return extended;
}

/**
 * Each
 *
 * @param {mixed} node list, array, object
 * @param {function} callback
 */
function each(collection, callback) {
  if (isNode(collection) || collection === window || collection === document) {
    collection = [collection];
  }
  if (!isArrayLike(collection) && !isObject(collection)) {
    collection = [collection];
  }
  if (size(collection) == 0) {
    return;
  }
  if (isArrayLike(collection) && !isObject(collection)) {
    let l = collection.length,
      i = 0;
    for (; i < l; i++) {
      if (callback.call(collection[i], collection[i], i, collection) === false) {
        break;
      }
    }
  } else if (isObject(collection)) {
    for (let key in collection) {
      if (has(collection, key)) {
        if (callback.call(collection[key], collection[key], key, collection) === false) {
          break;
        }
      }
    }
  }
}

/**
 * Get nde events
 * return node events and optionally
 * check if the node has already a specific event
 * to avoid duplicated callbacks
 *
 * @param {node} node
 * @param {string} name event name
 * @param {object} fn callback
 * @returns {object}
 */
function getNodeEvents(node, name = null, fn = null) {
  const cache = node[uid] = node[uid] || [];
  const data = {
    all: cache,
    evt: null,
    found: null
  };
  if (name && fn && size(cache) > 0) {
    each(cache, (cl, i) => {
      if (cl.eventName == name && cl.fn.toString() == fn.toString()) {
        data.found = true;
        data.evt = i;
        return false;
      }
    });
  }
  return data;
}

/**
 * Add Event
 * Add an event listener
 *
 * @param {string} eventName
 * @param {object} detials
 */
function addEvent(eventName, {
  onElement,
  withCallback,
  avoidDuplicate = true,
  once = false,
  useCapture = false
} = {}, thisArg) {
  let element = onElement || [];
  if (isString(element)) {
    element = document.querySelectorAll(element);
  }
  function handler(event) {
    if (isFunction(withCallback)) {
      withCallback.call(thisArg, event, this);
    }
    if (once) {
      handler.destroy();
    }
  }
  handler.destroy = function () {
    each(element, el => {
      const events = getNodeEvents(el, eventName, handler);
      if (events.found) {
        events.all.splice(events.evt, 1);
      }
      if (el.removeEventListener) {
        el.removeEventListener(eventName, handler, useCapture);
      }
    });
  };
  each(element, el => {
    const events = getNodeEvents(el, eventName, handler);
    if (el.addEventListener && avoidDuplicate && !events.found || !avoidDuplicate) {
      el.addEventListener(eventName, handler, useCapture);
      events.all.push({
        eventName: eventName,
        fn: handler
      });
    }
  });
  return handler;
}

/**
 * Add element class
 *
 * @param {node} element
 * @param {string} class name
 */
function addClass(node, name) {
  each(name.split(' '), cl => node.classList.add(cl));
}

/**
 * Remove element class
 *
 * @param {node} element
 * @param {string} class name
 */
function removeClass(node, name) {
  each(name.split(' '), cl => node.classList.remove(cl));
}

/**
 * Has class
 *
 * @param {node} element
 * @param {string} class name
 */
function hasClass(node, name) {
  return node.classList.contains(name);
}

/**
 * Get the closestElement
 *
 * @param {node} element
 * @param {string} class name
 */
function closest(elem, selector) {
  while (elem !== document.body) {
    elem = elem.parentElement;
    if (!elem) {
      return false;
    }
    const matches = typeof elem.matches == 'function' ? elem.matches(selector) : elem.msMatchesSelector(selector);
    if (matches) {
      return elem;
    }
  }
}

/**
 * CSS Animations
 *
 * @param {node} element
 * @param {string} animation name
 * @param {function} callback
 */
function animateElement(element, animation = '', callback = false) {
  if (!element || animation === '') {
    return false;
  }
  if (animation === 'none') {
    if (isFunction(callback)) {
      callback();
    }
    return false;
  }
  const animationEnd = whichAnimationEvent();
  const animationNames = animation.split(' ');
  each(animationNames, name => {
    addClass(element, 'g' + name);
  });
  addEvent(animationEnd, {
    onElement: element,
    avoidDuplicate: false,
    once: true,
    withCallback: (event, target) => {
      each(animationNames, name => {
        removeClass(target, 'g' + name);
      });
      if (isFunction(callback)) {
        callback();
      }
    }
  });
}
